<script setup lang="ts">
import SearchableCombobox from '@/components/SearchableCombobox.vue';
import AppLayout from '@/layouts/AppLayout.vue';
import { type BreadcrumbItem, type Project } from '@/types';
import { Head, Link, router } from '@inertiajs/vue3';
import { ArrowLeft, ChevronDown, ChevronUp, LoaderCircle, Plus, Trash2 } from 'lucide-vue-next';
import { computed, onMounted, ref, watch } from 'vue';

type SourceLine={id:number;label:string;article_reference?:string|null;line_note?:string|null;unit:string;quantity_received:number;quantity_transferred:number;quantity_available:number};
type Reception={id:number;received_at:string;purchase_order:{id:number;order_number?:string|null;title:string};lines:SourceLine[]};
type Allocation={project_id:string;project_responsible_id:string;project_query:string;transferred_at:string;reference:string;notes:string;lines:{reception_line_id:number;label:string;article_reference?:string|null;line_note?:string|null;unit:string;max:number;quantity_transferred:number}[]};
const props=defineProps<{projects:(Pick<Project,'id'|'code'|'name'>&{current_responsible_assignment?:{user_id:number;user?:{name:string}}|null})[];availableReceptions:Reception[];draft?:any}>();
const breadcrumbs:BreadcrumbItem[]=[{title:'Transferts chantiers',href:route('transfers.index')},{title:'Nouveau transfert',href:'#'}];
const receptionQuery=ref(''); const receptionId=ref(''); const showProgress=ref(false); const selected=ref<Reception|null>(null); const allocations=ref<Allocation[]>([]); const submitting=ref(false); const showReview=ref(false); const showProject=ref(false); const projectForm=ref({code:'',name:''});
const fmtDate=(v:string)=>new Date(v).toLocaleDateString('fr-FR'); const fmtQty=(v:number)=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v);
const receptionLabel=(r:Reception)=>`${r.purchase_order.order_number||r.purchase_order.title} — reçue le ${fmtDate(r.received_at)}`;
const projectLabel=(p:Pick<Project,'id'|'code'|'name'>)=>`${p.code} — ${p.name}`;
const receptionOptions=computed(()=>props.availableReceptions.map(r=>({value:String(r.id),label:r.purchase_order.order_number||r.purchase_order.title,description:`Reçue le ${fmtDate(r.received_at)} · ${r.lines.length} article(s)`})));
const projectOptions=computed(()=>props.projects.map(p=>({value:String(p.id),label:projectLabel(p),description:p.current_responsible_assignment?.user?.name?`Responsable : ${p.current_responsible_assignment.user.name}`:'Aucun responsable actif'})));
const storageKey=computed(()=>props.draft?`transfer-draft-${props.draft.id}`:'transfer-create-autosave');
function makeAllocation():Allocation{return{project_id:'',project_responsible_id:'',project_query:'',transferred_at:new Date().toISOString().slice(0,10),reference:'',notes:'',lines:(selected.value?.lines??[]).map(l=>({reception_line_id:l.id,label:l.label,article_reference:l.article_reference,line_note:l.line_note,unit:l.unit,max:l.quantity_available,quantity_transferred:0}))}}
function chooseReception(){selected.value=props.availableReceptions.find(r=>String(r.id)===receptionId.value)??null;receptionQuery.value=selected.value?receptionLabel(selected.value):'';allocations.value=selected.value?[makeAllocation()]:[]}
function chooseProject(a:Allocation){const p=props.projects.find(p=>String(p.id)===a.project_id);a.project_query=p?projectLabel(p):'';a.project_responsible_id=p?.current_responsible_assignment?String(p.current_responsible_assignment.user_id):''}
function fillAll(a:Allocation){for(const line of a.lines){const state=lineState(line.reception_line_id);const elsewhere=state?state.allocated-Number(line.quantity_transferred):0;line.quantity_transferred=Math.max(0,line.max-elsewhere)}}
function duplicateAllocation(source:Allocation){allocations.value.push({...source,reference:'',lines:source.lines.map(line=>({...line,quantity_transferred:0}))})}const lineTotals=computed(()=>(selected.value?.lines??[]).map(source=>{const allocated=allocations.value.reduce((total,allocation)=>total+Number(allocation.lines.find(line=>line.reception_line_id===source.id)?.quantity_transferred||0),0);return {...source,allocated,remaining:source.quantity_available-allocated,exceeded:allocated>source.quantity_available};}));
const hasExceeded=computed(()=>lineTotals.value.some(line=>line.exceeded));
const unallocatedLines=computed(()=>lineTotals.value.filter(line=>line.remaining>0));
const lineState=(id:number)=>lineTotals.value.find(line=>line.id===id);
const valid=computed(()=>Boolean(selected.value&&allocations.value.length&&!hasExceeded.value&&allocations.value.every(a=>a.project_id&&a.project_responsible_id&&a.lines.some(l=>Number(l.quantity_transferred)>0)&&a.lines.every(l=>Number(l.quantity_transferred)>=0))));
function createProject(){router.post(route('transfers.projects.store'),projectForm.value,{preserveScroll:true,onSuccess:()=>{showProject.value=false;projectForm.value={code:'',name:''}}})}
function submit(mode:'draft'|'confirmed'='confirmed'){if(!selected.value||!valid.value)return;submitting.value=true;if(props.draft){const a=allocations.value[0];router.put(route('transfers.update',props.draft.id),{project_id:a.project_id,project_responsible_id:a.project_responsible_id,transferred_at:a.transferred_at,reference:a.reference||null,notes:a.notes||null,lines:a.lines.filter(l=>Number(l.quantity_transferred)>0).map(l=>({reception_line_id:l.reception_line_id,quantity_transferred:l.quantity_transferred}))},{onSuccess:()=>localStorage.removeItem(storageKey.value),onFinish:()=>submitting.value=false});return}router.post(route('transfers.batch.store'),{reception_id:selected.value.id,mode,transfers:allocations.value.map(a=>({project_id:a.project_id,project_responsible_id:a.project_responsible_id,transferred_at:a.transferred_at,reference:a.reference||null,notes:a.notes||null,lines:a.lines.filter(l=>Number(l.quantity_transferred)>0).map(l=>({reception_line_id:l.reception_line_id,quantity_transferred:l.quantity_transferred}))}))},{onSuccess:()=>{localStorage.removeItem(storageKey.value);router.visit(route('transfers.index'))},onFinish:()=>submitting.value=false})}

onMounted(()=>{if(!props.draft){const saved=localStorage.getItem(storageKey.value);if(saved){try{const state=JSON.parse(saved);receptionId.value=state.receptionId||'';selected.value=props.availableReceptions.find(r=>String(r.id)===receptionId.value)??null;receptionQuery.value=selected.value?receptionLabel(selected.value):'';allocations.value=selected.value?(state.allocations||[]):[];if(selected.value&&allocations.value.length)return}catch{localStorage.removeItem(storageKey.value)}}const id=Number(new URLSearchParams(window.location.search).get('reception_id'));if(id){receptionId.value=String(id);chooseReception()}return;}selected.value=props.availableReceptions.find(r=>r.id===props.draft.reception_id)??null;if(!selected.value)return;receptionId.value=String(selected.value.id);receptionQuery.value=receptionLabel(selected.value);const project=props.projects.find(p=>p.id===props.draft.project_id);const allocation=makeAllocation();allocation.project_id=String(props.draft.project_id);allocation.project_responsible_id=String(props.draft.project_responsible_id);allocation.project_query=project?projectLabel(project):'';allocation.transferred_at=props.draft.transferred_at.slice(0,10);allocation.reference=props.draft.reference??'';allocation.notes=props.draft.notes??'';for(const saved of props.draft.lines){const line=allocation.lines.find(l=>l.reception_line_id===saved.reception_line_id);if(line)line.quantity_transferred=Number(saved.quantity_transferred)}allocations.value=[allocation]});
watch([receptionId,allocations],()=>{if(selected.value)localStorage.setItem(storageKey.value,JSON.stringify({receptionId:receptionId.value,allocations:allocations.value,updatedAt:new Date().toISOString()}))},{deep:true});</script>
<template><Head title="Nouveaux transferts"/><AppLayout :breadcrumbs="breadcrumbs"><div class="transfers-create flex w-full max-w-none flex-col gap-5 px-4 py-5 text-slate-950 sm:px-6 lg:px-8">
<div class="flex w-full flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div class="flex gap-3"><Link :href="route('transfers.index')" class="rounded-xl border bg-white p-2"><ArrowLeft class="h-5 w-5"/></Link><div><h1 class="text-2xl font-bold text-slate-950 lg:text-3xl">Créer des bons de transfert</h1><p class="text-sm text-slate-600">Répartissez une réception entre un ou plusieurs chantiers.</p></div></div><button class="text-sm font-semibold text-amber-700" @click="showProject=!showProject">+ Chantier absent</button></div>
<div v-if="showProject" class="grid gap-3 rounded-2xl border bg-white p-4 md:grid-cols-[1fr_2fr_auto]"><input v-model="projectForm.code" placeholder="Code chantier" class="h-10 rounded-xl border px-3"/><input v-model="projectForm.name" placeholder="Nom du chantier" class="h-10 rounded-xl border px-3"/><button class="rounded-xl bg-slate-900 px-4 text-white" @click="createProject">Créer</button></div>
<section class="w-full rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><label class="mb-2 block text-sm font-semibold text-slate-900">Réception source</label><SearchableCombobox v-model="receptionId" :options="receptionOptions" placeholder="Rechercher un BC ou une date…" empty-text="Aucune réception disponible" @update:model-value="chooseReception"/></section>
<template v-if="selected">
<section class="rounded-2xl border bg-white p-5 shadow-sm"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><h2 class="font-bold">Progression par article</h2><span class="rounded-full px-3 py-1 text-xs font-semibold" :class="unallocatedLines.length?'bg-amber-100 text-amber-800':'bg-emerald-100 text-emerald-800'">{{unallocatedLines.length?`${unallocatedLines.length} article(s) encore non affecté(s)`:'Tous les articles sont affectés'}}</span><button type="button" class="inline-flex items-center gap-2 rounded-xl border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-800 hover:bg-slate-50" @click="showProgress=!showProgress"><ChevronUp v-if="showProgress" class="h-4 w-4"/><ChevronDown v-else class="h-4 w-4"/>{{showProgress?'Masquer la progression':'Afficher la progression'}}</button></div><div v-if="showProgress" class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><div v-for="line in lineTotals" :key="line.id" class="rounded-xl border p-3" :class="line.exceeded?'border-red-300 bg-red-50':line.remaining>0?'border-amber-200 bg-amber-50/40':'border-emerald-200 bg-emerald-50/40'"><strong class="block truncate text-sm">{{line.label}}</strong><div class="mt-2 h-2 overflow-hidden rounded-full bg-slate-200"><div class="h-full rounded-full transition-all" :class="line.exceeded?'bg-red-500':line.remaining===0?'bg-emerald-500':'bg-blue-500'" :style="{width:`${Math.min(100,(line.quantity_transferred+line.allocated)/line.quantity_received*100)}%`}"/></div><div class="mt-2 grid grid-cols-4 gap-1 text-[11px]"><span>Reçu<strong class="block">{{fmtQty(line.quantity_received)}}</strong></span><span>Déjà transféré<strong class="block text-slate-600">{{fmtQty(line.quantity_transferred)}}</strong></span><span>Maintenant<strong class="block text-blue-700">{{fmtQty(line.allocated)}}</strong></span><span>Restant<strong class="block" :class="line.remaining<0?'text-red-700':'text-emerald-700'">{{fmtQty(line.remaining)}}</strong></span></div><p v-if="line.exceeded" class="mt-2 text-xs font-semibold text-red-700">Dépassement de {{fmtQty(-line.remaining)}} {{line.unit}}</p><p v-else-if="line.remaining>0" class="mt-2 text-xs font-medium text-amber-700">Encore {{fmtQty(line.remaining)}} {{line.unit}} à affecter</p></div></div></section><section v-for="(a,i) in allocations" :key="i" class="rounded-2xl border bg-white p-5 shadow-sm"><div class="mb-4 flex flex-wrap items-center justify-between gap-2"><h2 class="font-bold">Bon de transfert {{i+1}}</h2><div class="flex gap-2"><button type="button" class="rounded-lg border px-3 py-1.5 text-xs font-semibold text-emerald-700" @click="fillAll(a)">Tout affecter ici</button><button type="button" class="rounded-lg border px-3 py-1.5 text-xs font-semibold text-blue-700" @click="duplicateAllocation(a)">Dupliquer</button><button v-if="allocations.length>1" type="button" class="rounded-lg border px-2 text-red-600" @click="allocations.splice(i,1)"><Trash2 class="h-4 w-4"/></button></div></div><div class="grid gap-3 lg:grid-cols-4"><label class="text-xs lg:col-span-2">Chantier<SearchableCombobox v-model="a.project_id" class="mt-1" :options="projectOptions" placeholder="Rechercher par code ou nom…" empty-text="Aucun chantier trouvé" @update:model-value="chooseProject(a)"/></label><p class="rounded-xl bg-amber-50 px-3 py-2 text-xs"><span class="block text-slate-500">Responsable chantier</span><strong>{{props.projects.find(p=>String(p.id)===a.project_id)?.current_responsible_assignment?.user?.name||'Aucun responsable actif'}}</strong></p><label class="text-xs">Date<input v-model="a.transferred_at" type="date" class="mt-1 h-10 w-full rounded-xl border px-3"/></label><label class="text-xs">Référence<input v-model="a.reference" class="mt-1 h-10 w-full rounded-xl border px-3" placeholder="BS-2026-001"/></label></div>
<div class="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3"><label v-for="l in a.lines" :key="l.reception_line_id" class="rounded-xl border bg-slate-50 p-3 text-xs"><strong class="block text-sm">{{l.label}}</strong><span v-if="l.article_reference" class="block font-mono text-slate-500">{{l.article_reference}}</span><em v-if="l.line_note" class="block text-slate-500">{{l.line_note}}</em><span class="mt-2 flex items-center gap-2"><input v-model.number="l.quantity_transferred" type="number" min="0" :max="l.max" step="0.01" class="h-9 min-w-0 flex-1 rounded-lg border px-2 text-right" :class="lineState(l.reception_line_id)?.exceeded ? 'border-red-500 bg-red-50' : ''"/> / {{fmtQty(l.max)}} {{l.unit}}</span></label></div><label class="mt-3 block text-xs">Notes<input v-model="a.notes" class="mt-1 h-10 w-full rounded-xl border px-3"/></label></section>
<button class="flex w-full items-center justify-center gap-2 rounded-xl border-2 border-dashed border-amber-300 py-4 font-semibold text-amber-700" @click="allocations.push(makeAllocation())"><Plus class="h-4 w-4"/> Ajouter un autre bon / chantier</button><div class="flex justify-end gap-2"><button :disabled="!valid||submitting" class="inline-flex items-center gap-2 rounded-xl border border-amber-600 px-5 py-3 font-semibold text-amber-700 disabled:cursor-not-allowed disabled:opacity-50" @click="submit('draft')"><LoaderCircle v-if="submitting" class="h-4 w-4 animate-spin"/>{{submitting?'Enregistrement…':'Enregistrer en brouillon'}}</button><Link :href="route('transfers.index')" class="rounded-xl border bg-white px-5 py-3">Annuler</Link><button :disabled="!valid||submitting" class="rounded-xl bg-amber-600 px-6 py-3 font-semibold text-white disabled:opacity-50" @click="showReview=true">Vérifier et continuer</button></div></template>
<div v-if="showReview" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4"><div class="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-xl font-bold">Récapitulatif avant validation</h2><p class="mt-1 text-sm text-slate-600">{{allocations.length}} bon(s) seront créés depuis {{receptionQuery}}.</p><div class="mt-4 space-y-3"><div v-for="(a,i) in allocations" :key="i" class="rounded-xl border p-4"><div class="flex justify-between"><strong>Bon {{i+1}} — {{a.project_query}}</strong><span>{{fmtDate(a.transferred_at)}}</span></div><ul class="mt-2 space-y-1 text-sm"><li v-for="line in a.lines.filter(item=>Number(item.quantity_transferred)>0)" :key="line.reception_line_id" class="flex justify-between"><span>{{line.label}}</span><strong>{{fmtQty(line.quantity_transferred)}} {{line.unit}}</strong></li></ul></div></div><div class="mt-5 flex justify-end gap-2"><button :disabled="submitting" class="rounded-xl border px-5 py-2.5 disabled:cursor-not-allowed disabled:opacity-50" @click="showReview=false">Retour et modifier</button><button :disabled="submitting" class="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-5 py-2.5 font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50" @click="submit('confirmed')"><LoaderCircle v-if="submitting" class="h-4 w-4 animate-spin"/>{{submitting?'Enregistrement…':'Confirmer définitivement'}}</button></div></div></div>
</div></AppLayout></template>
<style scoped>.transfers-create{color:#0f172a}.transfers-create input,.transfers-create select,.transfers-create textarea{background:#fff!important;color:#0f172a!important;border-color:#cbd5e1!important}.transfers-create input::placeholder,.transfers-create textarea::placeholder{color:#64748b!important;opacity:1}.transfers-create h1,.transfers-create h2,.transfers-create label{color:#0f172a}.transfers-create section{width:100%;border-color:#e2e8f0}.transfers-create :deep(button){opacity:1}.transfers-create :deep(button > span.text-slate-500){color:#475569!important}</style>